  (* [comment removed for export] *)
  Ltac ax1_dec1_run pc0 pc1 q k lo_band :=
    lazymatch lo_band with
    | true =>
      kx_runFm [pc1] 100%nat
        [KZIdx tl (2^tl); KZRange (64 - tl) 52 63; KZRange tl 1 12; KZRange (2^tl) 2 4096;
         KZWr (DST + q + k) 1; KZDisj (DST + q + k) 1 (DT + 4) (2 * 2^tl);
         KZRange DT 0x5ed000 (2^47 - 8192); KZRange DST 0x5ed000 (0x7fff7000 - 4); KZRange q 0 (2^32);
         KZRange (DST + q + k) 0x5ed000 (0x7fff7000 - 1)]
        [(DT + 4, 2 * 2^tl)]
        [(DT + 4, 2 * 2^tl); (DST + q + k, 1)]
        [(DT + 4, 2 * 2^tl); (DST + q + k, 1)]
    | false =>
      kx_runFm [pc1] 100%nat
        [KZIdx tl (2^tl); KZRange (64 - tl) 52 63; KZRange tl 1 12; KZRange (2^tl) 2 4096;
         KZWr (DST + q + k) 1; KZDisj (DST + q + k) 1 (DT + 4) (2 * 2^tl);
         KZRange DT 0x5ed000 (2^47 - 8192); KZRange DST 0x10007fff8000 (2^47 - 4); KZRange q 0 (2^32);
         KZRange (DST + q + k) 0x10007fff8000 (2^47 - 1)]
        [(DT + 4, 2 * 2^tl)]
        [(DT + 4, 2 * 2^tl); (DST + q + k, 1)]
        [(DT + 4, 2 * 2^tl); (DST + q + k, 1)]
    end;
    try (lazymatch goal with |- evtF _ _ _ _ => fail | _ => unfold KXGoM.apart in *; lia end).

  Ltac ax1_dec1_post q k buf :=
    kx_post_regs_keep;
    lazymatch goal with H : u8arr asegs ?mm DST _, HL : log_flat _ _ |- _ =>
      let buf' := fresh "buf'" in let OUT' := fresh "OUT'" in let LB' := fresh "LB'" in
      destruct (kx_u8arr_ex asegs _ mm _ DST buf H HL) as (buf' & OUT' & LB') end;
    lazymatch goal with H : munch [(?a, ?b); (DST, ?c)] m0 ?mm |- _ =>
      let MUW := fresh "MUW" in let WMr := fresh "WMr" in
      pose proof (munch_refl [(DST + q + k, DST + q + k + 1)] mm) as MUW; pose proof (wmono_refl asegs mm) as WMr;
      kx_munch_wins MUW [(DST + q + k, 1)]; kx_munch_wins H [(DST + q + k, 1)] end;
    kx_post_mem_free;
    lazymatch goal with |- context [mem_denot ?E ?mm ?l] => let EM1 := fresh "EM1" in remember (mem_denot E mm l) as m1 eqn:EM1 end;
    lazymatch goal with H : u8arr asegs ?mm DST (map _ buf) |- _ => clear H end;
    unfold KXGoM.apart in DJ1, DJ2, DJ3;
    lazymatch goal with MUW' : munch [(DST + q + k, DST + q + k + 1)] ?mm ?m1', WMr' : wmono asegs ?mm ?m1' |- _ =>
      transport_after_call asegs mm m1' MUW' WMr' end;
    lazymatch goal with OUT' : u8arr asegs ?m1' DST (map _ ?b'), LB' : length ?b' = length buf |- _ =>
      assert (XM' : AX1M' m1')
        by (split; [exists b'; split; [exact OUT'| unfold zlen in *; rewrite LB'; assumption]|];
            repeat (split; [first [eassumption | eexists; eassumption]|]); first [eassumption | eexists; eassumption]) end.

  Ltac ax1_dec_facts mm MU :=
    pose proof (A1 ax1_unp mm MU) as (UDT' & UDB' & USB');
    pose proof (A1 ax1_blocks) as (B1 & B2 & B3 & B4 & B5 & B6); destruct (B6 ltac:(lia)) as (Q1 & Q2 & Q3 & Q4');
    pose proof (A1 ax1_sp_bounds) as SB; pose proof (A1 ax1_outb) as OB;
    pose proof (WDB ltac:(lia)) as WDB'; pose proof (WDBS ltac:(lia)) as WDBS';
    pose proof TOK as (TL & TC & TCK); unfold HUF_TABLELOG_MAX in TL; unfold FseNCount.Zlength in TC;
    assert (P2 : 2 <= 2 ^ tl <= 4096) by (split; [change 2 with (2^1) at 1 | change 4096 with (2^12)]; apply Z.pow_le_mono_r; lia);
    assert (DTLb : DT + 4 + 2 * 2^tl <= DT + DTABLE_BYTES mtl)
      by (unfold DTABLE_BYTES, HufHarness.DT_BYTES; assert (2^tl <= 2^(mtl+1)) by (apply Z.pow_le_mono_r; lia);
          rewrite Z.pow_add_r in * by lia; lia);
    assert (LCBn : Z.of_nat (length cbs) = 2 * 2 ^ tl) by exact LCB;
    assert (LSM : Z.of_nat (length (map (Z_to_bv 8) src)) = n) by (rewrite length_map; reflexivity);
    pose proof (bv_unsigned_in_range 64 sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
    unfold AIMG_HI, KLS in *.

  (* [comment removed for export] *)
  Lemma ax1_d3 : forall q pt mm (c w4 x11 x13 x15 x18 x19 x20 x21 x22 xra : word),
    AX1HK (q + 4) -> 0 <= q -> q + 4 <= dcap -> 0 <= pt -> (pt = 0 \/ pt + 8 <= n) -> AX1M' mm ->
    evtF asegs RNG POST (MS (mkR xra (Z_to_bv 64 SPF) gp tp (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DT + 4)) c (Z_to_bv 64 (64 - tl))
             (Z_to_bv 64 64) (Z_to_bv 64 (DST + q)) x11 (Z_to_bv 64 SS) x13 (Z_to_bv 64 (DST + q)) x15 (Z_to_bv 64 (tl + 256 * mtl))
             (Z_to_bv 64 2147450880) x18 x19 x20 x21 x22 s7 s8 s9 s10 s11 (Z_to_bv 64 pt) w4
             (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 8))
        FR (Z_to_bv 64 0x85728) fc None mm (seg_rom asegs)).
Proof using All.
